<#
.SYNOPSIS
  Rapihkan Win11 - a straightforward Windows 11 inspection and file organization tool.
#>
[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Interactive','Gui','Audit','StorageAnalysis','JunkScan','SafeCleanup','ApplySafeCleanup','DeepCleanup','BrowserScan','DeveloperScan','CacheReview','DuplicateScan','Organize','ApplyOrganize','ApplySelectedOrganize','Startup','Performance','StorageOptimize','HealthCheck','FullMaintenance','History','Quarantine','RestoreQuarantine','AddExclusion','RemoveExclusion','AddCategory','ScheduleAudit','RemoveSchedule')][string]$Mode='Interactive',
 [string[]]$Drive,[string]$Path,[string[]]$Source,[string]$ManifestPath,[string]$CategoryName,[string[]]$Extension,[string]$ScheduleTime='09:00',[switch]$ExportReport,[switch]$NonInteractive
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$root=$PSScriptRoot
Get-ChildItem -LiteralPath (Join-Path $root 'Modules') -Filter '*.ps1' -File|ForEach-Object {. $_.FullName};Initialize-ToolkitFolders
function Show-Header {Clear-Host;Write-Host '============================================================' -ForegroundColor Cyan;Write-Host '                    RAPIHKAN WIN11' -ForegroundColor Cyan;Write-Host '          Inspect your PC, review the advice, decide yourself' -ForegroundColor Cyan;Write-Host '============================================================' -ForegroundColor Cyan;try{$p=Get-PerformanceBaseline;$d=Get-PSDrive C;Write-Host "Computer: $env:COMPUTERNAME";Write-Host "CPU usage: $($p.CpuPercent)% | Memory: $($p.MemoryUsedPercent)% | C: free: $(Format-ByteSize $d.Free)"}catch{Write-Host 'The system overview could not be read.' -ForegroundColor Yellow};Write-Host 'Safe by default: checks do not change anything. File actions need 3 approvals.' -ForegroundColor Yellow}
function Invoke-Mode {param([string]$SelectedMode,[string]$SelectedPath);switch($SelectedMode){'Gui'{Start-RapihkanGui};'Audit'{Invoke-SystemAudit -Drive $Drive};'StorageAnalysis'{Get-StorageAnalysis -Path $(if($SelectedPath){$SelectedPath}elseif($Path){$Path}else{'C:\'})};'JunkScan'{@(Find-JunkCandidates)};'SafeCleanup'{Invoke-SafeCleanup};'ApplySafeCleanup'{Invoke-SafeCleanup -Apply};'DeepCleanup'{Invoke-DeepCleanup};'BrowserScan'{@(Find-BrowserCache)};'DeveloperScan'{@(Find-DeveloperCache)};'CacheReview'{@(Get-CacheReview)};'DuplicateScan'{@(Find-DuplicateFiles -Path $(if($SelectedPath){$SelectedPath}elseif($Path){$Path}else{$env:USERPROFILE}))};'Organize'{@(Get-OrganizationPlan -Path $(if($SelectedPath){$SelectedPath}elseif($Path){$Path}else{(Join-Path $env:USERPROFILE 'Downloads')}))};'ApplyOrganize'{Invoke-FileOrganization -Path $(if($SelectedPath){$SelectedPath}elseif($Path){$Path}else{(Join-Path $env:USERPROFILE 'Downloads')}) -Apply};'ApplySelectedOrganize'{Invoke-SelectedOrganizationPlan -Path $Path -Source $Source};'Startup'{@(Get-StartupAnalysis)};'Performance'{Get-PerformanceBaseline};'StorageOptimize'{@(Get-StorageOptimizationAnalysis)};'HealthCheck'{Get-SystemHealthCheck};'FullMaintenance'{[pscustomobject]@{SystemSummary=Invoke-SystemAudit;Performance=Get-PerformanceBaseline;WindowsHealth=Get-SystemHealthCheck;TemporaryFiles=@(Find-JunkCandidates)}};'History'{@(Get-RapihkanHistory)};'Quarantine'{@(Get-QuarantineItems)};'RestoreQuarantine'{Restore-RapihkanQuarantineItem -ManifestPath $ManifestPath};'AddExclusion'{Add-UserExclusion -Path $Path};'RemoveExclusion'{Remove-UserExclusion -Path $Path};'AddCategory'{Add-OrganizationCategory -Name $CategoryName -Extensions $Extension};'ScheduleAudit'{Register-RapihkanAuditSchedule -Time $ScheduleTime};'RemoveSchedule'{Unregister-RapihkanAuditSchedule}}}
function Read-MenuPath {param([string]$Prompt,[string]$Default);$v=Read-Host "$Prompt [$Default]";if([string]::IsNullOrWhiteSpace($v)){$v=$Default};if(!(Test-Path -LiteralPath $v -PathType Container)){Write-Host "Folder not found: $v" -ForegroundColor Red;return $null};(Resolve-Path -LiteralPath $v).Path}
function Invoke-WithStatus {param([string]$Name,[scriptblock]$Work);Write-Host "`n$Name is running..." -ForegroundColor Cyan;Write-Progress -Activity 'Rapihkan Win11' -Status "${Name}: preparing" -PercentComplete 10;try{Write-Progress -Activity 'Rapihkan Win11' -Status "${Name}: analyzing" -PercentComplete 55;& $Work}finally{Write-Progress -Activity 'Rapihkan Win11' -Status "${Name}: finishing" -PercentComplete 100;Write-Progress -Activity 'Rapihkan Win11' -Completed}}
function Show-Result {param($Result,[string]$Title,[string]$ActionMode,[string]$ActionPath);Write-Host "`n--- Result: $Title ---" -ForegroundColor Cyan;if($null -eq $Result){Write-Host 'No results were found.' -ForegroundColor Yellow;return};$Result|Format-List *|Out-Host;if($ActionMode -and (Read-Host 'Run the safe recommended action now? (y/N)') -match '^(y|yes)$'){Show-Result (Invoke-WithStatus 'Running safe action' {Invoke-Mode $ActionMode $ActionPath}) 'Action complete' $null $null};if((Read-Host 'Save these results as a local report? (y/N)') -match '^(y|yes)$'){$f=Export-ToolkitData -Data $Result -BaseName "$Title-$(Get-NowStamp)";$h=New-ToolkitHtmlReport -Data $Result -Title $Title;Write-Host "Report saved to: $($f.Json)" -ForegroundColor Green;Write-Host "HTML report: $h" -ForegroundColor Green};[void](Read-Host 'Press Enter to return to the menu')}
function Start-InteractiveMenu {do{Show-Header;Write-Host @'

 CHOOSE WHAT TO CHECK
 [01] Check your computer             [10] Review startup apps
 [02] Find large files and folders    [11] Check current performance
 [03] Find temporary files            [12] Review storage care advice
 [04] Clean up temporary files        [13] Check Windows health
 [05] Review deeper cleanup advice    [14] Run all key checks
 [06] Review browser cache            [15] Open reports folder
 [07] Review work-app cache           [16] Open activity log
 [08] Find duplicate files            [17] Run tool tests
 [09] Plan folder organization        [18] How it works and safety
 [19] Open portable desktop window    [20] View action history
 [21] Review Quarantine                [22] Review app caches

 [00] Exit
'@ -ForegroundColor White;$c=(Read-Host 'Enter an option number').Trim().PadLeft(2,'0');if($c -eq '00'){break};try{switch($c){'01'{Show-Result (Invoke-WithStatus 'Checking computer status' {Invoke-Mode Audit}) 'Computer status' $null $null}'02'{$p=Read-MenuPath 'Folder to inspect' 'C:\';if($p){Show-Result (Invoke-WithStatus 'Finding large files' {Invoke-Mode StorageAnalysis $p}) 'Storage use' $null $null}}'03'{Show-Result (Invoke-WithStatus 'Finding temporary files' {Invoke-Mode JunkScan}) 'Temporary files' $null $null}'04'{Show-Result (Invoke-WithStatus 'Preparing cleanup advice' {Invoke-Mode SafeCleanup}) 'Temporary-file advice' 'ApplySafeCleanup' $null}'05'{Show-Result (Invoke-WithStatus 'Reviewing deeper cleanup' {Invoke-Mode DeepCleanup}) 'Deeper cleanup advice' $null $null}'06'{Show-Result (Invoke-WithStatus 'Reviewing browser cache' {Invoke-Mode BrowserScan}) 'Browser data' $null $null}'07'{Show-Result (Invoke-WithStatus 'Reviewing work-app cache' {Invoke-Mode DeveloperScan}) 'Work-app data' $null $null}'08'{$p=Read-MenuPath 'Folder to search for duplicates' $env:USERPROFILE;if($p){Show-Result (Invoke-WithStatus 'Finding duplicate files' {Invoke-Mode DuplicateScan $p}) 'Duplicate files' $null $null}}'09'{$p=Read-MenuPath 'Folder to organize' (Join-Path $env:USERPROFILE 'Downloads');if($p){Show-Result (Invoke-WithStatus 'Creating organization plan' {Invoke-Mode Organize $p}) 'Folder organization plan' 'ApplyOrganize' $p}}'10'{Show-Result (Invoke-WithStatus 'Reviewing startup apps' {Invoke-Mode Startup}) 'Startup apps' $null $null}'11'{Show-Result (Invoke-WithStatus 'Checking performance' {Invoke-Mode Performance}) 'Computer performance' $null $null}'12'{Show-Result (Invoke-WithStatus 'Reviewing storage' {Invoke-Mode StorageOptimize}) 'Storage care advice' $null $null}'13'{Show-Result (Invoke-WithStatus 'Checking Windows health' {Invoke-Mode HealthCheck}) 'Windows health' $null $null}'14'{Show-Result (Invoke-WithStatus 'Running all key checks' {Invoke-Mode FullMaintenance}) 'Computer summary' $null $null}'15'{Start-Process (Join-Path (Get-ToolkitPaths).Reports 'Audit')}'16'{Start-Process (Get-ToolkitPaths).Logs}'17'{& "$root\Tests\Toolkit-Tests.ps1" -ToolkitRoot $root;& "$root\Tests\Path-Validation-Tests.ps1" -ToolkitRoot $root;& "$root\Tests\Safety-Tests.ps1" -ToolkitRoot $root;[void](Read-Host 'Press Enter')}'18'{Write-Host 'Choose a check, read the result, then choose an action if available. File actions require you to type YES three times and create a local record.' -ForegroundColor Yellow;[void](Read-Host 'Press Enter')}'19'{Start-RapihkanGui}'20'{Show-Result (Invoke-Mode History) 'Action history' $null $null}'21'{Show-Result (Invoke-Mode Quarantine) 'Quarantine items' $null $null}'22'{Show-Result (Invoke-WithStatus 'Reviewing application caches' {Invoke-Mode CacheReview}) 'Application cache review' $null $null};default{Write-Host 'That option is not available. Try again.' -ForegroundColor Red;Start-Sleep 1}}}catch{Write-Host "The check could not finish: $($_.Exception.Message)" -ForegroundColor Red;Write-ToolkitLog ERROR $_.Exception.Message 'Menu';[void](Read-Host 'Press Enter')}}while($true)}
if($Mode -eq 'Interactive' -and !$NonInteractive){Start-InteractiveMenu;return}
$result=Invoke-Mode $Mode $Path;if($ExportReport){Export-ToolkitData -Data $result -BaseName "$Mode-$(Get-NowStamp)"|Out-Null;New-ToolkitHtmlReport -Data $result -Title $Mode|Out-Null};$result